#include <bits/stdc++.h>
using namespace std;

#define FAST ios_base::sync_with_stdio(false);cin.tie(NULL);
#define endl '\n'

typedef long long ll;
typedef pair<int,int> pii;

int dx[]={1,-1,0,0};
int dy[]={0,0,1,-1};

struct FlowEdge {
    int v, u;
    long long cap, flow=0;
    FlowEdge(int v, int u, long long cap): v(v), u(u), cap(cap) {}
};

struct DinicFlow {
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    int n, m=0, s, t;
    vector<int> level, ptr;
    queue<int> q;

    DinicFlow(int n, int s, int t): n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add_edge(int v, int u, long long cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(m);
        adj[u].push_back(m+1);
        m+=2;
    }

    bool bfs() {
        while(!q.empty()) q.pop();
        fill(level.begin(), level.end(), -1);
        level[s]=0;
        q.push(s);
        while(!q.empty()) {
            int v=q.front(); q.pop();
            for (int id: adj[v]) {
                if (edges[id].cap - edges[id].flow <1) continue;
                if (level[edges[id].u]!=-1) continue;
                level[edges[id].u]=level[v]+1;
                q.push(edges[id].u);
            }
        }
        return level[t]!=-1;
    }

    long long push_flow(int v, long long flow_in) {
        if (v==t) return flow_in;
        for (int& cid=ptr[v]; cid<(int)adj[v].size(); cid++) {
            int id=adj[v][cid];
            int u=edges[id].u;
            if (level[v]+1!=level[u] || edges[id].cap - edges[id].flow<1) continue;
            long long pushed=push_flow(u, min(flow_in, edges[id].cap - edges[id].flow));
            if (pushed>0) {
                edges[id].flow+=pushed;
                edges[id^1].flow-=pushed;
                return pushed;
            }
        }
        return 0;
    }

    long long compute_max_flow() {
        long long total=0;
        while(bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed=push_flow(s, 1e18))
                total+=pushed;
        }
        return total;
    }
};

int main() {
    int n, t;
    cin>>n>>t;
    vector<string> sci(n), cap(n);
    for (int i=0; i<n; i++) cin>>sci[i];
    for (int i=0; i<n; i++) cin>>cap[i];

    int dis[15][15], dis2[15][15];

    auto valid_cell = [&](int x, int y) {
        if (x<0 || y<0 || x>=n || y>=n) return false;
        if (sci[x][y]=='Y' || sci[x][y]=='Z') return false;
        return true;
    };

    auto compute_distances = [&](int x, int y) {
        queue<pii> q;
        q.push({x,y});
        memset(dis, -1, sizeof dis);
        dis[x][y]=0;
        while (!q.empty()) {
            auto u=q.front(); q.pop();
            for (int i=0; i<4; i++) {
                int vx=u.first+dx[i], vy=u.second+dy[i];
                if (valid_cell(vx, vy) && dis[vx][vy]==-1) {
                    dis[vx][vy]=dis[u.first][u.second]+1;
                    q.push({vx, vy});
                }
            }
        }
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                if (dis[i][j]==-1) dis[i][j]=1000000000;
            }
        }
    };

    int dp[65][12][12][12][12];
    memset(dp, -1, sizeof dp);

    auto can_reach = [&](int t_curr, int x0, int y0, int x, int y) {
        if (dis[x0][y0]<t_curr) return 0;
        if (x0==x && y0==y) return 1;
        if (t_curr>=t) return 0;
        if (dis[x0][y0]<=t_curr) return 0;
        if (dp[t_curr][x0][y0][x][y]!=-1) return dp[t_curr][x0][y0][x][y];
        for (int j=0; j<4; j++) {
            int xx=x0+dx[j], yy=y0+dy[j];
            if (xx<0 || xx>=n || yy<0 || yy>=n) continue;
            if (sci[xx][yy]=='Y' || sci[xx][yy]=='Z') continue;
            if (can_reach(t_curr+1, xx, yy, x, y))
                return dp[t_curr][x0][y0][x][y]=1;
        }
        return dp[t_curr][x0][y0][x][y]=0;
    };

    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (sci[i][j]=='Z') compute_distances(i,j);
        }
    }

    vector<pii> sources, sinks;
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (sci[i][j]!='Z' && sci[i][j]!='Y' && sci[i][j]!='0') {
                sources.push_back({i,j});
            }
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (cap[i][j]!='Z' && cap[i][j]!='Y' && cap[i][j]!='0') {
                sinks.push_back({i,j});
            }
        }
    }

    int total_nodes = (int)sources.size() + (int)sinks.size() + 2;
    DinicFlow flow(total_nodes, 0, total_nodes-1);
    for (int i=0; i<(int)sources.size(); i++) {
        ll c=sci[sources[i].first][sources[i].second]-'0';
        flow.add_edge(0, i+1, c);
    }
    for (int i=0; i<(int)sinks.size(); i++) {
        ll c=cap[sinks[i].first][sinks[i].second]-'0';
        flow.add_edge((int)sources.size()+1+i, total_nodes-1, c);
    }
    for (int i=0; i<(int)sources.size(); i++) {
        for (int j=0; j<(int)sinks.size(); j++) {
            if (can_reach(0, sources[i].first, sources[i].second, sinks[j].first, sinks[j].second))
                flow.add_edge(i+1, (int)sources.size()+1+j, 10000000);
        }
    }

    cout << flow.max_flow() << endl;
}
